function BusComp_SetFieldValue (FieldName)
{
	if(FieldName == "MF Credit Seg2 Code"){

		var segCode_c = this.GetFieldValue("MF Credit Seg2 Code");

		if(segCode_c!=null && segCode_c!=""){
			var segCode_c2 = F_ReplaceKanji(segCode_c);
			this.SetFieldValue("MF Credit Seg2 Code - Kanji Rep",segCode_c2);
		}
	}
	if(FieldName == "MF Debit Seg2 Code"){

		var segCode_d = this.GetFieldValue("MF Debit Seg2 Code");

		if(segCode_d!=null && segCode_d!=""){
			var segCode_d2 = F_ReplaceKanji(segCode_d);
			this.SetFieldValue("MF Debit Seg2 Code - Kanji Rep",segCode_d2);
		}
	}
}
function F_ReplaceKanji(VIN){
	var replaced = "";
	for (var i = 0; i < VIN.length; i++) {
        var code = VIN.charCodeAt(i);
        // Kanji ranges
        if((code >= 0x3040 && code <= 0x309F) ||  // Hiragana
            (code >= 0x30A0 && code <= 0x30FF) ||  // Katakana
            (code >= 0x4E00 && code <= 0x9FFF) ||  // Kanji
            (code >= 0x3400 && code <= 0x4DBF) ||  // Kanji Extension A
            (code >= 0xF900 && code <= 0xFAFF) ||  // Compatibility Ideographs
            (code >= 0xFF61 && code <= 0xFF9F))     // Half-width Katakana
		{
            replaced += "X";
        }
		else if (code >= 0xFF01 && code <= 0xFF5E) 
		{
            // Full-width ASCII range: normalize to regular ASCII
            replaced+=String.fromCharCode(code - 0xFEE0);
        }
		else
		{
			replaced += VIN.charAt(i);
        }
    }
	return replaced;
}

