function ApprovalHistoryCheck(sId) {
    try {
        var TheApp = TheApplication();
        var oAppFlowHistoryBO = TheApp.GetBusObject("MF Approval History");
        var oAppFlowHistoryBC = oAppFlowHistoryBO.GetBusComp("MF Approval Flow History");
        var bcMVF, sExpr = "";
        with(oAppFlowHistoryBC) {
            SetViewMode(AllView);
            ClearToQuery();
            sExpr = "[MF Entity Id] = '" + sId + "' AND [MF Status] = 'Pending for Approval' AND [MF Sequence] = '1'";
            SetSearchExpr(sExpr);
            ExecuteQuery(ForwardOnly);
            if (FirstRecord()) {
                bcMVF = GetMVGBusComp("MFApprovers");
                with(bcMVF) {
                    SetViewMode(AllView);
                    ClearToQuery();
                    ExecuteQuery(ForwardOnly);
                    if (!FirstRecord()) {
                        HistoryRecordDelete(sId);
                        EntityRecordDelete(sId);
                        TheApp.RaiseErrorText("Approvers do not exist for the given position");
                    }
                }
            }
        }
    } catch (e) {
        throw (e);
    } finally {
        bcMVF = null;
        oAppFlowHistoryBC = null;
        oAppFlowHistoryBO = null;
        TheApp = null;
    }
}

function HistoryRecordDelete(sId) {
    try {
        var oAppFlowHistoryBO = TheApplication().GetBusObject("MF Approval History");
        var oAppFlowHistoryBC = oAppFlowHistoryBO.GetBusComp("MF Approval Flow History");
        with(oAppFlowHistoryBC) {
            SetViewMode(AllView);
            ClearToQuery();
            SetSearchExpr("[MF Entity Id] = '" + sId + "'");
            ExecuteQuery(ForwardOnly);
            while (FirstRecord()) {
                DeleteRecord();
            }
        }
    } catch (e) {
        throw (e);
    } finally {
        oAppFlowHistoryBC = null;
        oAppFlowHistoryBO = null;
    }
}

function EntityRecordDelete(sId) {
    try {
        var oAppFlowEntityBC = TheApplication().GetBusObject("MF Approval History").GetBusComp("MF Entity Approval Flow");
        with(oAppFlowEntityBC) {
            ActivateField("Entity Id");
            ActivateField("Status");
            SetViewMode(AllView);
            ClearToQuery();
            SetSearchSpec("Entity Id", sId);
            ExecuteQuery(ForwardOnly);
            while (FirstRecord()) {
                DeleteRecord();
            }
        }
    } catch (e) {
        throw (e);
    } finally {
        oAppFlowEntityBC = null;
    }
}
